/**
 * Expo config plugin: marks `android.hardware.screen.portrait` as NOT required (TASK-031).
 *
 * Why: `orientation: 'portrait'` makes Android/Play infer that the app requires a portrait-capable
 * screen, which hides it from landscape-only devices (Android XR, some tablets, ChromeOS, TV).
 * The activity stays locked to portrait; an explicit `required="false"` only lifts the
 * device-availability restriction. The android/ folder is regenerated by `expo prebuild`, so the
 * plugin re-applies it every time.
 */
const { withAndroidManifest } = require('expo/config-plugins');

const FEATURE = 'android.hardware.screen.portrait';

/** Ensures exactly one optional portrait <uses-feature> (object form from xml2js). */
function setPortraitOptional(manifest) {
  const others = (manifest['uses-feature'] || []).filter((f) => f.$['android:name'] !== FEATURE);
  manifest['uses-feature'] = [
    ...others,
    { $: { 'android:name': FEATURE, 'android:required': 'false' } },
  ];
  return manifest;
}

function withOptionalPortrait(config) {
  return withAndroidManifest(config, (cfg) => {
    setPortraitOptional(cfg.modResults.manifest);
    return cfg;
  });
}

module.exports = withOptionalPortrait;
module.exports.setPortraitOptional = setPortraitOptional;
